import{_ as a,o as e,c as d,a3 as s}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"移动端设计语言与 Varlet 降级决议","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mobile-design-language.md","filePath":"guide/mobile-design-language.md","lastUpdated":1784790670000}'),o={name:"guide/mobile-design-language.md"};function l(n,t,i,r,p,c){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="移动端设计语言与-varlet-降级决议" tabindex="-1">移动端设计语言与 Varlet 降级决议 <a class="header-anchor" href="#移动端设计语言与-varlet-降级决议" aria-label="Permalink to &quot;移动端设计语言与 Varlet 降级决议&quot;">​</a></h1><blockquote><p><strong>状态</strong>: Accepted v4.2 <strong>作者</strong>: miaotouy / 咕咕 / Codex <strong>日期</strong>: 2026-06-09 <strong>前提</strong>: 移动端尚未对外发布，仍处于内部构建阶段，<strong>无线上兼容性债务</strong></p></blockquote><hr><h2 id="版本演进" tabindex="-1">版本演进 <a class="header-anchor" href="#版本演进" aria-label="Permalink to &quot;版本演进&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>核心命题</th><th>状态</th></tr></thead><tbody><tr><td>v1</td><td>把&quot;玻璃质感&quot;当作 AIO Hub 的 DNA</td><td>错判</td></tr><tr><td>v2</td><td>DNA 修正为&quot;高度可定制视觉系统 + 品牌一致性元素&quot;，但仍在&quot;换不换 UI 库&quot;的框架里讨论</td><td>不彻底</td></tr><tr><td>v3</td><td>跳出&quot;UI 库选型&quot;框架，提出组件抽象层路线，但直接把自研 <code>base/</code> 写成既定结论</td><td>武断</td></tr><tr><td>v3.1</td><td>修正为&quot;先组件适配性调查，再决定 Varlet 降级范围&quot;</td><td>已被 v4 覆盖</td></tr><tr><td>v4</td><td><strong>直接决议：Varlet 降级为底层组件库。移动端整体仍以 Vue 原生组件、项目 CSS token 和业务自研骨架为主</strong></td><td>已被 v4.1 覆盖</td></tr><tr><td>v4.1</td><td>补充 AIO Hub 产品定位：不是传统小工具合集，而是在统一框架下承载复杂能力、降低使用门槛的工具枢纽</td><td>已被 v4.2 覆盖</td></tr><tr><td>v4.2</td><td>修正 §3/§5 的&quot;照搬桌面端组件清单&quot;问题，改为需求驱动式沉淀</td><td>当前版本</td></tr></tbody></table><hr><h2 id="_0-当前决议" tabindex="-1">0. 当前决议 <a class="header-anchor" href="#_0-当前决议" aria-label="Permalink to &quot;0. 当前决议&quot;">​</a></h2><p>这次不再继续围绕&quot;Varlet 是否适合承担移动端框架&quot;做开放式调查。实际体验已经给出结论：</p><blockquote><p><strong>Varlet 的默认设计语言和主题气质不适合作为 AIO Hub Mobile 的整体框架。</strong> 它可以留下来，像桌面端的 Element Plus 一样提供底层组件能力；但不能继续决定移动端页面骨架、主题表现、容器语义和默认审美。</p></blockquote><p>移动端的新定位：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tauri v2 + Vue 3 + TypeScript + Rust</span></span>
<span class="line"><span>  ├─ AIO Hub 自有主题 token / 质感系统 / 品牌细节</span></span>
<span class="line"><span>  ├─ Vue 原生组件与业务组件承担页面骨架</span></span>
<span class="line"><span>  ├─ mobile/src/components/common 沉淀跨工具通用组件</span></span>
<span class="line"><span>  ├─ mobile/src/components/base/ 沉淀移动端基础容器与交互骨架</span></span>
<span class="line"><span>  └─ Varlet 仅作为可替换的底层组件库</span></span></code></pre></div><p>一句话：<strong>移动端是 AIO Hub 的 Vue/Tauri 移动实现，不是 Varlet/MD3 应用。</strong></p><p>同时需要修正一个容易误导后续设计的表述：AIO Hub 不是纯粹的&quot;小工具集合&quot;，也不是只面向强专业用户的冷硬工具箱。桌面端很多功能已经在持续做两件事：一是把复杂能力装进更顺手的交互里，降低用户理解和使用成本；二是在统一的工具框架下，让新能力可以快速开发、注册和接入，甚至不需要反复改路由和主框架。</p><p>因此，移动端不应把自己设计成&quot;一个木函&quot;、&quot;图吧工具箱&quot;这类传统工具合集的移动复刻。它更接近一个可扩展的 AI 工具枢纽：既允许单个工具轻量接入，也允许像桌面端 Chat 那样成长为完整、强大的系统级能力。</p><hr><h2 id="_1-设计-dna" tabindex="-1">1. 设计 DNA <a class="header-anchor" href="#_1-设计-dna" aria-label="Permalink to &quot;1. 设计 DNA&quot;">​</a></h2><h3 id="_1-1-默认形象" tabindex="-1">1.1 默认形象 <a class="header-anchor" href="#_1-1-默认形象" aria-label="Permalink to &quot;1.1 默认形象&quot;">​</a></h3><p>桌面端默认状态的真实气质是：</p><table tabindex="0"><thead><tr><th>维度</th><th>桌面端默认</th></tr></thead><tbody><tr><td>背景</td><td>纯色，跟随明暗主题</td></tr><tr><td>UI 层</td><td>不透明卡片，无默认玻璃</td></tr><tr><td>主题色</td><td><code>#409eff</code> Element Plus 蓝</td></tr><tr><td>状态色</td><td>绿 / 橙 / 红 / 灰，克制工具色板</td></tr><tr><td>边框</td><td>1px 标准实线</td></tr><tr><td>圆角</td><td>中等克制</td></tr><tr><td>头像</td><td>圆角矩形，非圆形</td></tr><tr><td>图标</td><td>Lucide 线性图标</td></tr><tr><td>布局</td><td>信息密度较高，但强调顺手、连续、可理解的工作流</td></tr></tbody></table><p>移动端允许更适合触屏的间距、字号和单栏流程，但默认气质不应被收窄成&quot;严肃专业的小工具箱&quot;。它应是<strong>干净、可靠、上手成本低、能承载复杂能力的 AIO Hub 工具枢纽</strong>：轻量工具可以快速并入，复杂工具也能拥有完整体验；不是 Material Design 模板应用，也不是一套 Varlet 主题样板。</p><h3 id="_1-2-高定制态" tabindex="-1">1.2 高定制态 <a class="header-anchor" href="#_1-2-高定制态" aria-label="Permalink to &quot;1.2 高定制态&quot;">​</a></h3><p>质感系统是 AIO Hub 的能力，而不是默认妆效：</p><ul><li>壁纸基底</li><li>半透明层</li><li><code>backdrop-filter: blur(var(--ui-blur)</code></li><li>主题色自动取色</li><li>卡片/弹层/导航透明度分层</li><li>性能降级策略</li></ul><p>移动端后续应移植这套能力，但默认不把玻璃、MD3 动态色或 Varlet 主题当作产品识别本身。</p><h3 id="_1-3-架构-dna" tabindex="-1">1.3 架构 DNA <a class="header-anchor" href="#_1-3-架构-dna" aria-label="Permalink to &quot;1.3 架构 DNA&quot;">​</a></h3><p>桌面端的真实分层是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页面骨架 / 业务容器 / 复杂交互  -&gt; 自研 Vue 组件</span></span>
<span class="line"><span>通用能力组件                -&gt; src/components/common/</span></span>
<span class="line"><span>按钮 / 输入 / 选择等原子件     -&gt; Element Plus</span></span>
<span class="line"><span>命令式消息与弹窗              -&gt; customMessage / BaseDialog 等项目封装</span></span></code></pre></div><p>这套分层的价值不只是&quot;组件自研&quot;或&quot;看起来统一&quot;，更重要的是让功能开发可以无痛并入统一框架：工具按 registry 接入，页面和服务能力按约定组织，主应用不为每个新工具反复改动路由和骨架。移动端应该继承的是这种可扩展产品框架，而不是把所有能力压平成松散入口列表。</p><p>移动端应对齐这套思想：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页面骨架 / 工具容器 / 移动交互  -&gt; 自研 Vue 组件</span></span>
<span class="line"><span>移动端基础组件                -&gt; mobile/src/components/base/</span></span>
<span class="line"><span>跨工具通用组件                -&gt; mobile/src/components/common/</span></span>
<span class="line"><span>按钮 / 输入 / 选择等原子件     -&gt; Varlet 可用但不主导</span></span>
<span class="line"><span>命令式消息与弹窗              -&gt; customMessage / customDialog 项目封装</span></span></code></pre></div><hr><h2 id="_2-varlet-新定位" tabindex="-1">2. Varlet 新定位 <a class="header-anchor" href="#_2-varlet-新定位" aria-label="Permalink to &quot;2. Varlet 新定位&quot;">​</a></h2><h3 id="_2-1-可以保留的范围" tabindex="-1">2.1 可以保留的范围 <a class="header-anchor" href="#_2-1-可以保留的范围" aria-label="Permalink to &quot;2.1 可以保留的范围&quot;">​</a></h3><p>Varlet 可以继续用于：</p><ul><li><code>var-button</code></li><li><code>var-input</code></li><li><code>var-select</code></li><li><code>var-switch</code></li><li><code>var-slider</code></li><li><code>var-checkbox</code></li><li><code>var-radio</code></li><li><code>var-chip</code></li><li>\`var-loading其他低风险、叶子节点级组件</li><li><code>Snackbar</code> / <code>Dialog</code> 的底层实现，但必须经项目封装后调用</li></ul><p>这些组件的角色与桌面端的 <code>&lt;el-button&gt;</code>、<code>&lt;el-input&gt;</code>、<code>&lt;el-select&gt;</code> 类似：<strong>省实现成本，但不定义产品骨架。</strong></p><h3 id="_2-2-不应继续承担的范围" tabindex="-1">2.2 不应继续承担的范围 <a class="header-anchor" href="#_2-2-不应继续承担的范围" aria-label="Permalink to &quot;2.2 不应继续承担的范围&quot;">​</a></h3><p>以下组件不应作为新增页面或重构后的主结构来源：</p><ul><li><code>var-app-bar</code></li><li><code>var-popup</code></li><li><code>var-cell</code></li><li><code>var-card</code></li><li><code>var-paper</code></li><li><code>var-bottom-navigation</code></li><li><code>var-style-provider</code> 对项目主题的主导权</li></ul><p>已有代码可以渐进迁移，但新增代码不要继续扩大这些组件的结构性占比。</p><h3 id="_2-3-命令式-api" tabindex="-1">2.3 命令式 API <a class="header-anchor" href="#_2-3-命令式-api" aria-label="Permalink to &quot;2.3 命令式 API&quot;">​</a></h3><p>业务代码不应继续散落：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Snackbar, Dialog } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@varlet/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>目标是统一替换为：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { customMessage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@/utils/customMessage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { customDialog } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@/utils/customDialog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>底层仍可调用 Varlet，但调用点必须收敛，API 与桌面端习惯对齐。</p><hr><h2 id="_3-目标分层" tabindex="-1">3. 目标分层 <a class="header-anchor" href="#_3-目标分层" aria-label="Permalink to &quot;3. 目标分层&quot;">​</a></h2><h3 id="_3-1-目录结构" tabindex="-1">3.1 目录结构 <a class="header-anchor" href="#_3-1-目录结构" aria-label="Permalink to &quot;3.1 目录结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mobile/src/</span></span>
<span class="line"><span>├── components/</span></span>
<span class="line"><span>│   ├── base/                # 按需沉淀，不预设清单</span></span>
<span class="line"><span>│   ├── common/                    # 按需沉淀，不照搬桌面端</span></span>
<span class="line"><span>│   │   ├── DynamicIcon.vue        # 已有：工具图标渲染需要</span></span>
<span class="line"><span>│   │   ├── IconPresetSelector.vue # 已有：llm-api 图标选择需要</span></span>
<span class="line"><span>│   └── （后续按实际需求增长）</span></span>
<span class="line"><span>│   └── AppBottomNav.vue</span></span>
<span class="line"><span>├── tools/</span></span>
<span class="line"><span>│   └── {toolId}/</span></span>
<span class="line"><span>│       ├── views/</span></span>
<span class="line"><span>│       ├── components/</span></span>
<span class="line"><span>│       └── {toolId}.registry.ts</span></span>
<span class="line"><span>├── stores/</span></span>
<span class="line"><span>│   └── theme.ts                # 输出 AIO token，兼容写入 Varlet 变量</span></span>
<span class="line"><span>└── utils/</span></span>
<span class="line"><span>    ├── customMessage.ts</span></span>
<span class="line"><span>    ├── customDialog.ts├── errorHandler.ts</span></span>
<span class="line"><span>    ├── logger.ts</span></span>
<span class="line"><span>    └── ...</span></span></code></pre></div><h3 id="_3-2-沉淀原则" tabindex="-1">3.2 沉淀原则 <a class="header-anchor" href="#_3-2-沉淀原则" aria-label="Permalink to &quot;3.2 沉淀原则&quot;">​</a></h3><p>组件沉淀采用<strong>需求驱动</strong>，不采用&quot;对照桌面端清单预建&quot;：</p><ul><li><strong><code>base/</code></strong>: 当某个 Varlet 容器组件确实在多处造成气质问题或定制困难时，才提取对应的 Base 组件。不预设完整清单，不要求一口气补齐。</li><li><strong><code>common/</code></strong>: 当某个功能（如头像、文件图标等）在两个以上工具中出现实际需求时，才沉淀通用组件。桌面端有的组件可以作为<strong>设计参考</strong>，但移动端实现应基于移动端自身的场景和交互模式重新设计，不是代码搬运。</li></ul><h3 id="_3-3-已知的未来需求-参考-非硬性清单" tabindex="-1">3.3 已知的未来需求（参考，非硬性清单） <a class="header-anchor" href="#_3-3-已知的未来需求-参考-非硬性清单" aria-label="Permalink to &quot;3.3 已知的未来需求（参考，非硬性清单）&quot;">​</a></h3><p>以下组件在移动端功能扩展过程中大概率会需要，但具体实现时机和形态应由实际场景决定：</p><table tabindex="0"><thead><tr><th>组件</th><th>触发条件</th><th>备注</th></tr></thead><tbody><tr><td>Avatar</td><td>Chat 功能完善、用户档案系统接入时</td><td>按移动端场景重新设计，不照搬桌面端</td></tr><tr><td>BaseAppBar</td><td>当 <code>var-app-bar</code> 的样式限制成为多页面痛点时</td><td>目前 var-app-bar 基本够用</td></tr><tr><td>BaseSheet</td><td>当 <code>var-popup</code> 无法满足自定义需求时</td><td>目前 var-popup 用着还行</td></tr><tr><td>BaseListItem</td><td>当 <code>var-cell</code> 在设置页的气质/定制问题频繁出现时</td><td>这是当前使用最密集的容器组件（40+ 处）</td></tr></tbody></table><hr><h2 id="_4-主题规则" tabindex="-1">4. 主题规则 <a class="header-anchor" href="#_4-主题规则" aria-label="Permalink to &quot;4. 主题规则&quot;">​</a></h2><h3 id="_4-1-主从关系" tabindex="-1">4.1 主从关系 <a class="header-anchor" href="#_4-1-主从关系" aria-label="Permalink to &quot;4.1 主从关系&quot;">​</a></h3><p>主题主从关系必须明确：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AIO Hub token -&gt; 移动端 Vue/CSS 组件 -&gt; Varlet 兼容变量</span></span></code></pre></div><p>不能倒过来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Varlet / MD3 token -&gt; AIO Hub 主题</span></span></code></pre></div><h3 id="_4-2-必备项目-token" tabindex="-1">4.2 必备项目 token <a class="header-anchor" href="#_4-2-必备项目-token" aria-label="Permalink to &quot;4.2 必备项目 token&quot;">​</a></h3><p>移动端至少应稳定维护下列项目级变量：</p><table tabindex="0"><thead><tr><th>类型</th><th>变量示例</th></tr></thead><tbody><tr><td>品牌色</td><td><code>--primary-color</code></td></tr><tr><td>状态色</td><td><code>--success-color</code> / <code>--warning-color</code> / <code>--danger-color</code> / <code>--info-color</code></td></tr><tr><td>背景</td><td><code>--bg-color</code> / <code>--card-bg</code> / <code>--container-bg</code> / \`--input</td></tr><tr><td>文本</td><td><code>--text-color</code> / <code>--text-secondary-color</code></td></tr><tr><td>边框</td><td><code>--border-color</code> / <code>--border-width</code></td></tr><tr><td>圆角</td><td><code>--app-radius-sm</code> / <code>--app-radius-md</code> / <code>--app-radius-lg</code></td></tr><tr><td>质感</td><td><code>--ui-blur</code> / <code>--card-opacity</code></td></tr><tr><td>安全区</td><td><code>--app-safe-area-top</code> / <code>--app-top-offset</code></td></tr></tbody></table><p>Varlet 变量只能作为适配输出，用于让保留的 <code>var-*</code> 原子件不突兀。</p><h3 id="_4-3-视觉禁区" tabindex="-1">4.3 视觉禁区 <a class="header-anchor" href="#_4-3-视觉禁区" aria-label="Permalink to &quot;4.3 视觉禁区&quot;">​</a></h3><ul><li>不要把 Material Design 3 当作移动端视觉基准。</li><li>不要让大面积 <code>var-card</code> / <code>var-paper</code> 形成统一的 Varlet 味。</li><li>不要用 Varlet 默认圆角、阴影、surface 分层决定 AIO 的默认观感。</li><li>不要把 <code>StyleProvider</code> 的主题输出当成唯一主题源。</li></ul><hr><h2 id="_5-迁移路线" tabindex="-1">5. 迁移路线 <a class="header-anchor" href="#_5-迁移路线" aria-label="Permalink to &quot;5. 迁移路线&quot;">​</a></h2><h3 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h3><p>迁移不按&quot;先造组件库再替换&quot;的顺序执行。正确的驱动力是：<strong>哪里痛就先动哪里，在动的过程中按需沉淀 base/common 组件。</strong></p><p>桌面端的通用组件（Avatar、BaseDialog 等）都是在实际功能开发中被逼出来的，移动端也应该走同样的路径。</p><h3 id="phase-0-规范落地-已完成" tabindex="-1">Phase 0：规范落地（已完成） <a class="header-anchor" href="#phase-0-规范落地-已完成" aria-label="Permalink to &quot;Phase 0：规范落地（已完成）&quot;">​</a></h3><ul><li>更新 <code>AGENTS.md</code>，明确移动端 UI 分层。</li><li>同步修正&quot;专业工具箱 / 小工具合集&quot;式描述。</li><li>将本文件作为移动端设计语言的当前决议。</li></ul><h3 id="phase-1-收敛命令式-api" tabindex="-1">Phase 1：收敛命令式 API <a class="header-anchor" href="#phase-1-收敛命令式-api" aria-label="Permalink to &quot;Phase 1：收敛命令式 API&quot;">​</a></h3><ol><li>建立 <code>mobile/src/utils/customMessage.ts</code>，包装 Varlet <code>Snackbar</code>。</li><li>建立 <code>mobile/src/utils/customDialog.ts</code>，包装 Varlet <code>Dialog</code>。</li><li>替换业务代码里散落的 <code>Snackbar</code> / <code>Dialog</code> 直接调用。</li><li>底层仍用 Varlet，但业务层只看项目 API。</li></ol><h3 id="phase-2-需求驱动的渐进迁移" tabindex="-1">Phase 2+：需求驱动的渐进迁移 <a class="header-anchor" href="#phase-2-需求驱动的渐进迁移" aria-label="Permalink to &quot;Phase 2+：需求驱动的渐进迁移&quot;">​</a></h3><p>不预设固定的 Phase 2/3/4/5 顺序。以下是可能的迁移方向，按<strong>实际开发中碰到痛点</strong>时触发：</p><p><strong>气质层面（视觉主导权）</strong>：</p><ul><li>当 <code>var-cell</code> 在设置页面的样式覆盖越来越痛时 → 提取 <code>BaseListItem</code></li><li>当 <code>var-app-bar</code> 限制了顶部栏的品牌表达时 → 提取 <code>BaseAppBar</code></li><li>当 <code>var-popup</code> 无法满足弹层定制需求时 → 提取 <code>BaseSheet</code></li></ul><p><strong>功能层面（新功能驱动）</strong>：</p><ul><li>当 Chat 完善到需要自定义头像体系时 → 按移动端场景设计 <code>Avatar</code></li><li>当多个工具都需要底部抽屉交互时 → 从实现中抽取通用骨架</li></ul><p><strong>主题层面</strong>：</p><ul><li>主题 store 已在输出 AIO Hub 项目 token，Varlet 变量作为派生兼容层</li><li>质感系统（壁纸、模糊、透明度）在移动端按需逐步移植</li><li>低端 Android 设备保留 <code>backdrop-filter</code> 降级策略</li></ul><h3 id="判断标准" tabindex="-1">判断标准 <a class="header-anchor" href="#判断标准" aria-label="Permalink to &quot;判断标准&quot;">​</a></h3><p>什么时候该动某个 Varlet 容器组件？</p><ol><li><strong>新功能开发时</strong>：如果新页面/功能用 Varlet 容器搭骨架，会导致后续定制成本高于自建 → 直接用 Vue 原生写</li><li><strong>维护痛点时</strong>：某个 Varlet 容器的样式覆盖 <code>:deep()</code> 已经累积到影响可维护性 → 提取替代组件</li><li><strong>气质冲突时</strong>：某个 Varlet 容器的默认视觉在整体页面中明显格不入 → 替换</li></ol><p>什么时候<strong>不</strong>急着动？</p><ul><li>用着没明显问题、样式覆盖可控 → 留着</li><li>只在测试页面（如 ui-tester）使用 → 不管它</li></ul><hr><h2 id="_6-新增代码规则" tabindex="-1">6. 新增代码规则 <a class="header-anchor" href="#_6-新增代码规则" aria-label="Permalink to &quot;6. 新增代码规则&quot;">​</a></h2><p>新增移动端页面时遵循：</p><ul><li>优先写语义清楚的 Vue 结构，不用 Varlet 容器搭页面。</li><li>页面级组件放 <code>views/</code>，工具内部业务组件放 <code>tools/{toolId}/components/</code>。</li><li>跨工具可复用的移动端骨架进 <code>components/base/</code>。</li><li>跨工具品牌/通用组件进 <code>components/common/</code>。</li><li>Varlet 只在叶子节点使用；如果必须用作结构容器，代码注释或 PR 说明里写明这是临时兼容。</li><li>不新增裸 <code>Snackbar</code> / <code>Dialog</code> 业务调用。</li><li>不新增以 MD3 / Varlet 变量为主语的主题设计。</li></ul><hr><h2 id="_7-当前债务清单" tabindex="-1">7. 当前债务清单 <a class="header-anchor" href="#_7-当前债务清单" aria-label="Permalink to &quot;7. 当前债务清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>债务</th><th>紧迫度</th><th>处理方向</th></tr></thead><tbody><tr><td><code>Snackbar</code> / <code>Dialog</code> 散落</td><td>高</td><td>先封装再替换</td></tr><tr><td><code>var-cell</code> 承担设置/列表信息架构（40+ 处）</td><td>中</td><td>碰到定制痛点时逐步替换，不急于一次性迁移</td></tr><tr><td><code>var-app-bar</code> 承担页面顶部栏（~12 处）</td><td>低</td><td>目前够用，品牌需求驱动时再动</td></tr><tr><td><code>var-popup</code> 承担编辑器骨架（~11 处）</td><td>低</td><td>目前够用，不急</td></tr><tr><td><code>var-paper</code> 承担分组容器（~6 处）</td><td>低</td><td>CSS 几行就能替代，不单独排期</td></tr><tr><td>主题仍有 MD3/Varlet 主导痕迹</td><td>中</td><td>持续反转为 AIO token 主导</td></tr></tbody></table><hr><h2 id="_8-决议记录" tabindex="-1">8. 决议记录 <a class="header-anchor" href="#_8-决议记录" aria-label="Permalink to &quot;8. 决议记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>决议项</th><th>结论</th><th>决议人</th></tr></thead><tbody><tr><td>2026-06-09</td><td>Varlet 定位</td><td>降级为类似桌面端 Element Plus 的底层组件库</td><td>用户</td></tr><tr><td>2026-06-09</td><td>移动端整体实现</td><td>以 Vue 原生组件、项目 CSS token 和自研业务骨架为主</td><td>用户</td></tr><tr><td>2026-06-09</td><td>主题方向</td><td>AIO Hub token 主导，Varlet 变量只是兼容输出</td><td>用户</td></tr><tr><td>2026-06-09</td><td>产品定位</td><td>AIO Hub 是统一框架下的可扩展能力枢纽，不是传统小工具合集</td><td>用户</td></tr><tr><td>2026-06-09</td><td>组件沉淀策略</td><td>需求驱动，不照搬桌面端清单；弹窗类当前够用不急着替换</td><td>用户</td></tr></tbody></table><hr><h2 id="_9-修订历史" tabindex="-1">9. 修订历史 <a class="header-anchor" href="#_9-修订历史" aria-label="Permalink to &quot;9. 修订历史&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>变更</th></tr></thead><tbody><tr><td>v1</td><td>2026-05-31</td><td>初稿，误把&quot;用户高定制态&quot;当作产品默认形象</td></tr><tr><td>v2</td><td>2026-05-31</td><td>修正 DNA 为&quot;高度可定制视觉系统 + 品牌一致性元素&quot;</td></tr><tr><td>v2.1</td><td>2026-05-31</td><td>删除错误的底部 V 形品牌锚点</td></tr><tr><td>v3</td><td>2026-05-31</td><td>提出组件抽象层路线，但把全量自研写得过早</td></tr><tr><td>v3.1</td><td>2026-05-31</td><td>改为先组件适配性调查，再决定下沉清单</td></tr><tr><td>v4</td><td>2026-06-09</td><td>根据实际体验直接决议：Varlet 降级为底层组件库，移动端回到 Vue 原生组件和 AIO 自有主题主导</td></tr><tr><td>v4.1</td><td>2026-06-09</td><td>修正产品定位表述：强调 AIO Hub 不是传统小工具合集，而是在统一框架下承载复杂能力、降低使用门槛的工具枢纽</td></tr><tr><td>v4.2</td><td>2026-06-09</td><td>修正 §3/§5 的照搬桌面端问题：组件清单改为需求驱动式沉淀，迁移路线改为痛点触发而非预建组件库</td></tr></tbody></table>`,104)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
